local SettingsCustomizeModel = (...)local PRESETID_CLASSIC = 0local PRESETID_NEW = 1local PRESETID_ACCESSIBLE = 2local CATEGORY_GAMEPAD_ATTACK = 0local CATEGORY_GAMEPAD_DEFENSE = 1local CATEGORY_GAMEPAD_TACTICS = 2local ACT_SETTINGS_CHANGE = "act_settings_change"local ACT_TYPE_CHANGE = "act_type_change"local ACT_ADVANCED_CHANGE = "act_advanced_change"local ACT_RESET_DEFAULTS = "act_reset_all"local CONTROLLERID_GAMEPAD = 0local SUB_TYPE_CONTROLLERID = 0local GAMEPAD_A_BUTTON = {keyCode = "VB_AI_A"}local GAMEPAD_B_BUTTON = {keyCode = "VB_AI_B"}local GAMEPAD_X_BUTTON = {keyCode = "VB_AI_X"}local GAMEPAD_Y_BUTTON = {keyCode = "VB_AI_Y"}local GAMEPAD_L_STICK = {keyCode = "VB_AI_LS"}local GAMEPAD_R_STICK = {keyCode = "VB_AI_RS"}local GAMEPAD_RT_BUTTON = {keyCode = "VB_AI_RT"}local GAMEPAD_RB_BUTTON = {keyCode = "VB_AI_RB"}local GAMEPAD_LT_BUTTON = {keyCode = "VB_AI_LT"}local GAMEPAD_LB_BUTTON = {keyCode = "VB_AI_LB"}local GAMEPAD_DPAD_LEFT = {  keyCode = "VB_AI_LDPAD_LEFT"}local GAMEPAD_DPAD_RIGHT = {  keyCode = "VB_AI_LDPAD_RIGHT"}local GAMEPAD_DPAD_UP = {  keyCode = "VB_AI_LDPAD_UP"}local GAMEPAD_DPAD_DOWN = {  keyCode = "VB_AI_LDPAD_DOWN"}local ControllerControls = {}function ControllerControls:new(init)  local o = init or {}  setmetatable(o, self)  self.__index = self  o.models = {    SettingsCustomizeModel = SettingsCustomizeModel:new({      im = o.im,      api = o.api,      nav = o.nav,      loc = o.loc    })  }  o.services = {    GameStateService = o.api("GameStateService"),    FifaCustomizationService = o.api("FifaCustomizationService")  }  o.isInGame = type(o.data) == "table" and o.data.ingame or false  o.defaultConfig = o.services.FifaCustomizationService.GetControllerConfiguration()  o.preset = o.defaultConfig  o.offense = true  o.basic = true  o.im.RegisterDataAction("bnd_controll_settings_index", ACT_SETTINGS_CHANGE, function(bindingName, actionName, index)    if index == 1 then      o.offense = false    else      o.offense = true    end    o:setList()    o:_toggleBasicAndAdvanced()  end  )  o.im.RegisterDataAction("bnd_controll_type_index", ACT_TYPE_CHANGE, function(bindingName, actionName, index)    o.preset = index    if index == PRESETID_NEW then      o.services.FifaCustomizationService.SetKeyboardConfiguration(CONTROLLERID_GAMEPAD, 1)    elseif index == PRESETID_ACCESSIBLE then      o.services.FifaCustomizationService.SetKeyboardConfiguration(CONTROLLERID_GAMEPAD, 2)    elseif index == PRESETID_CLASSIC then      o.services.FifaCustomizationService.SetKeyboardConfiguration(CONTROLLERID_GAMEPAD, 0)    end    o:setList()    o:_toggleBasicAndAdvanced()  end  )  o.im.RegisterDataAction("bnd_controll_advanced_index", ACT_ADVANCED_CHANGE, function(bindingName, actionName, index)    if index == 1 then      o.basic = false    else      o.basic = true    end    o:setList()    o:_toggleBasicAndAdvanced()  end  )  o.im.RegisterAction(ACT_RESET_DEFAULTS, function(actionName, data)    local title = "LTXT_RESET_TO_DEFAULT"    local desc = o.loc.LocalizeString("ConfirmDiscardChanges")    function onConfirmAction()      o.basic = true      o.preset = PRESETID_CLASSIC      o.offense = true      o.services.FifaCustomizationService.SetKeyboardConfiguration(CONTROLLERID_GAMEPAD, 0)      o:_publishControllSettingsList()      o:_publishControllAdvancedList()      o:_publishControllTypeList()      o:setList()      o:_toggleBasicAndAdvanced()    end        o.models.SettingsCustomizeModel:showPopup(title, desc, onConfirmAction)  end  )  o.im.Subscribe("bnd_controll_settings_list", function()    o:_publishControllSettingsList()  end  )  o.im.Subscribe("bnd_controll_type_list", function()    o:_publishControllTypeList()  end  )  o.im.Subscribe("bnd_controll_advanced_list", function()    o:_publishControllAdvancedList()  end  )  o.im.Subscribe("bnd_controll_type_list_enabled", function()    o.im.Publish("bnd_controll_type_list_enabled", not o.isInGame)  end  )  o.im.Subscribe("bnd_basic_group_v", function()    o.im.Publish("bnd_basic_group_v", o.basic == true)  end  )  o.im.Subscribe("bnd_advanced_group_v", function()    o.im.Publish("bnd_advanced_group_v", o.basic == false)  end  )  o.im.Subscribe("bnd_basic_controller_list_data", function()    o:setList()  end  )  o.im.Subscribe("bnd_advanced_controller_list_data", function()    o:setList()  end  )  o:_toggleBasicAndAdvanced()  return oendfunction ControllerControls:playMovie(binding, play)  self.im.Publish(binding, play)endfunction ControllerControls:_toggleBasicAndAdvanced()  self.im.Publish("bnd_basic_group_v", self.basic == true)  self.im.Publish("bnd_advanced_group_v", self.basic == false)endfunction ControllerControls:setList()  print("ControllerControls:setList")  if self.basic then    if self.offense then      if self.preset == PRESETID_ACCESSIBLE then        self:_publishBasicAttackingTwoButton()      else        self:_publishBasicAttackingControlsList()      end    elseif self.preset == PRESETID_ACCESSIBLE then      self:_publishBasicDefendingTwoButton()    else      self:_publishBasicDefendingControlsList()    end  elseif self.offense then    if self.preset == PRESETID_ACCESSIBLE then      self:_publishAdvancedAttackingTwoButton()    else      self:_publishAdvancedAttackingControlsList()    end  elseif self.preset == PRESETID_ACCESSIBLE then    self:_publishAdvancedDefendingTwoButton()  else    self:_publishAdvancedDefendingControlsList()  endendfunction ControllerControls:_publishControllSettingsList()  local dataList = {    {      text = self.loc.LocalizeString("LTXT_CONTROLS_ATTACKING_TITLE")    },    {      text = self.loc.LocalizeString("LTXT_CONTROLS_DEFENDING_TITLE")    }  }  local dataToPublish = {data = dataList, index = 0}  self.im.Publish("bnd_controll_settings_list", dataToPublish)endfunction ControllerControls:_publishControllAdvancedList()  local dataList = {    {      text = self.loc.LocalizeString("LTXT_SETTINGS_CONTROL_BASIC")    },    {      text = self.loc.LocalizeString("LTXT_SETTINGS_CONTROL_ADVANCED")    }  }  local dataToPublish = {data = dataList, index = 0}  self.im.Publish("bnd_controll_advanced_list", dataToPublish)endfunction ControllerControls:_publishControllTypeList()  local dataList = {    {      text = self.loc.LocalizeString("LTXT_SETTINGS_CONTROL_CLASSIC")    },    {      text = self.loc.LocalizeString("LTXT_SETTINGS_CONTROL_ALTERNATE")    },    {      text = self.loc.LocalizeString("LTXT_SETTINGS_CONTROL_TWO_BUTTONS")    }  }  local dataToPublish = {data = dataList, index = 0}  self.im.Publish("bnd_controll_type_list", dataToPublish)endfunction ControllerControls:_publishButtonsLabel(binding, label)  self.im.Publish(binding, label)endfunction ControllerControls:_GetGamepadButtonBorX()  if self.preset == PRESETID_NEW then    return GAMEPAD_B_BUTTON  elseif self.preset == PRESETID_CLASSIC then    return GAMEPAD_X_BUTTON  end  return {}endfunction ControllerControls:_GetGamepadButtonXorB()  if self.preset == PRESETID_NEW then    return GAMEPAD_X_BUTTON  elseif self.preset == PRESETID_CLASSIC then    return GAMEPAD_B_BUTTON  end  return {}endfunction ControllerControls:_publishBasicAttackingTwoButton()  local dirtyIndices = {}  local nRows = 7  do    do      for i = 0, nRows do        table.insert(dirtyIndices, i)      end    end  end  local dataList = {    dirty = dirtyIndices,    data = {      {        data = {          actions = {GAMEPAD_A_BUTTON},          description = self.loc.LocalizeString("LTXT_SETTINGS_ACTION42")        }      },      {        data = {          actions = {            GAMEPAD_A_BUTTON,            self.loc.LocalizeString("LTXT_CONTROL_HOLD")          },          description = self.loc.LocalizeString("LTXT_SETTINGS_ACTION40")        }      },      {        data = {          acti